program='''def transform(grid):
    g=[r[:] for r in grid]
    pts={c:[(r,k) for r,row in enumerate(grid) for k,v in enumerate(row) if v==c] for c in range(1,10)}
    def put(r,c,v):
        if 0<=r<len(g) and 0<=c<len(g[0]): g[r][c]=v
    def line(a,b,v):
        r,c=a; R,C=b
        if r==R:
            for x in range(min(c,C),max(c,C)+1): put(r,x,v)
        elif c==C:
            for x in range(min(r,R),max(r,R)+1): put(x,c,v)
    # Straight lines specified by two endpoints.
    for v in (1,2,4,6):
        p=pts[v]
        if len(p)==2 and (p[0][0]==p[1][0] or p[0][1]==p[1][1]): line(p[0],p[1],v)
    # A small right angle bordering a vertical magenta line.
    if len(pts[4])==1 and len(pts[6])==2:
        r,c=pts[4][0]; p=sorted(pts[6])
        if (r,c)==(p[0][0]-1,p[0][1]-1) and p[0][1]==p[1][1]:
            line((r,c),(p[1][0],c),4); line((r,c),(r,c+2),4)
    # Rectangular outlines.
    if len(pts[1])==4:
        rs=sorted(set(r for r,c in pts[1])); cs=sorted(set(c for r,c in pts[1]))
        if len(rs)==len(cs)==2:
            a,b=rs; c,d=cs
            line((a,c),(a,d),1); line((b,c),(b,d),1); line((a,c),(b,c),1); line((a,d),(b,d),1)
            if len(pts[8])==1 and pts[8][0]==(a-1,c-1):
                line((a-1,c-1),(b-1,c-1),8); line((a-1,c-1),(a-1,d-1),8)
                line((b-1,c-1),(b-1,d-1),8); line((a-1,d-1),(b-1,d-1),8)
    if len(pts[1])==2 and len(pts[8])==4:
        rs=[r for r,c in pts[8]]; cs=[c for r,c in pts[8]]
        a,b=min(rs),max(rs); c,d=min(cs),max(cs)
        line((a,c),(a,d),8); line((b,c),(b,d),8); line((a,c),(b,c),8); line((a,d),(b,d),8)
        line((a,c),(b,c),1); line((a,d),(b,d),1)
    # Diamond outline of green cells.
    if len(pts[3])==4:
        rs=[r for r,c in pts[3]]; cs=[c for r,c in pts[3]]
        a,b=min(rs),max(rs); c,d=min(cs),max(cs)
        if b-a==d-c and (b-a)%2==0:
            m=(a+b)//2; n=(c+d)//2
            for r in range(a,b+1):
                dist=min(r-a,b-r)
                put(r,n-dist,3); put(r,n+dist,3)
    # Nested magenta/orange partial diamonds.
    if len(pts[6])==3 and len(pts[7])==1:
        rs=[r for r,c in pts[6]+pts[7]]; cs=[c for r,c in pts[6]+pts[7]]
        a=min(rs); n=pts[6][0][1]
        for k in range(1,6):
            put(a+k,n-k,7); put(a+k,n+k,7)
            if k>1: put(a+k,n-k+1,6); put(a+k,n+k-1,6)
        put(a,n,6); put(a-1,n,7); put(a+6,n-5,6); put(a+6,n+5,6); put(a+7,n-4,6); put(a+7,n+6,6); put(a+8,n-3,7)
    # Square spiral.
    if len(pts[7])==5:
        a=min(r for r,c in pts[7]); b=max(r for r,c in pts[7]); c=min(c for r,c in pts[7]); d=max(c for r,c in pts[7])
        line((a,c),(a,d-1),7); line((a,c),(b,c),7); line((a,d),(a+2,d),7)
        for k in range(2,b-a-1): put(a+k,d-k,7)
        line((b,c),(b,c+2),7)
    return g
'''
